	@Test
	void exhaustedStateCapacityRefusesOriginsWhileKeepingQualifiedNativeQuantities() throws Exception {
		try (Fixture fixture = new Fixture(Endpoint.END, 0L, false, 1);
				PackedCostSession session = fixture.model.openSession(fixture.call.query())) {
			int source = fixture.priceFilteredPrefix(session);
			int assignment = fixture.call.query().childRelationId(fixture.call.leftRelationId(), 0);
			int last = 0;
			for (int attempts = 0; attempts <= 8192; attempts++) {
				PackedCostEstimate leaf = new PackedCostEstimate();
				session.estimateLeaf(assignment, fixture.call.emptyContext(), leaf);
				if (leaf.evidenceStateId() == 0) {
					break;
				}
				last = leaf.evidenceStateId();
			}
			assertEquals(8192, last, "exercise the existing state cap without changing it");
			LmdbFrontierStatisticsCostSession mapped = (LmdbFrontierStatisticsCostSession) session;
			int origins = mapped.originNodeCount();
			declare(fixture, RowScope.FOR_CONTEXT, CostScope.TOTAL_FOR_CONTEXT, 7.0d, 37.0d, false);
			for (int attempt = 0; attempt < 3; attempt++) {
				PackedCostEstimate output = new PackedCostEstimate();
				output.setRows(attempt == 0 ? 101.0d : Double.NaN, Double.NaN);
				session.appendFactor(fixture.call.rightRelationId(), fixture.restrictedContext(source), output);
				assertEquals(7.0d, output.outputRows());
				assertTrue(output.hasContextualOutputRows());
				assertTrue(output.hasExplicitPhysicalCost());
				assertEquals(33.0d, output.workRows(), "typed resource sum replaces isolated work independently");
				assertEquals(0, output.evidenceStateId());
				assertEquals(EvidenceGuarantee.SCALAR_FALLBACK, output.evidenceGuarantee());
				assertEquals(FrontierStateDisposition.BOUND_ONLY, output.evidenceDisposition());
				assertEquals(origins, mapped.originNodeCount(), "refusal must not consume origin nodes");
			}
		}
	}

