			learnedJoin.setResultSizeActual(1000L);
			learnedJoin.setLongMetricActual(TelemetryMetricNames.OUTPUT_ROWS_ACTUAL, 1000L);
			learnedJoin.setLongMetricActual(TelemetryMetricNames.CLOSE_COUNT_ACTUAL, 1L);
			learnedJoin.setLongMetricActual(TelemetryMetricNames.EXHAUSTED_CLOSE_COUNT_ACTUAL, 1L);
			learnedJoin.setHasNextCallCountActual(1001L);
			learnedJoin.setHasNextTrueCountActual(1000L);
