			learnedJoin.setJoinRightBindingsConsumedActual(101L);
			LmdbOperatorFeedbackStats feedback = new LmdbOperatorFeedbackStats(directory.resolve("operators"));
			feedback.recordOperatorOutcome(learnedJoin);
			var available = feedback.estimate(learnedJoin.clone(), 2.0d, 101.0d, 7.0d, 71.0d);
			assertNotNull(available, "the actual supported JOIN feedback provider must answer");
			assertTrue(available.rows() > 7.0d);
			AtomicInteger calls = new AtomicInteger();
			AtomicReference<LmdbOperatorFeedbackStats.OperatorEstimate> returned = new AtomicReference<>();
			when(fixture.runtime.operatorFeedback(any(), anyDouble(), anyDouble(), anyDouble(), anyDouble(), any()))
					.thenAnswer(invocation -> {
						calls.incrementAndGet();
						var result = feedback.estimate(invocation.getArgument(0), invocation.getArgument(1),
								invocation.getArgument(2), invocation.getArgument(3), invocation.getArgument(4),
								invocation.getArgument(5));
						returned.set(result);
						return result;
					});
			PackedCostEstimate qualified = new PackedCostEstimate();
			qualified.setContextualRows(7.0d, 71.0d);
			qualified.setEstimateProvenance("supplemental-join", "provider-control");
			session.refineOperator(fixture.call.operatorRelationId(), fixture.call.operatorContext(
					2.0d, 101.0d, semanticLeft, semanticRight.evidenceStateId()), qualified);
			assertEquals(1, calls.get(), "qualified inputs must reach the exposed logical provider");
			assertNotNull(returned.get());
			assertEquals(returned.get().rows(), qualified.outputRows());
			assertFalse(qualified.hasContextualOutputRows());
