	@ParameterizedTest
	@MethodSource("outputOrigins")
	void actualBindingOnlyOutputCannotEnterLegacyFeedbackWithStateFreeContext(boolean foreignOutput,
			@TempDir Path directory) throws Exception {
		try (Fixture target = new Fixture(Endpoint.END, 0L, false, 1);
				Fixture producer = new Fixture(Endpoint.END, 0L, false, 1);
				PackedCostSession targetSession = target.model.openSession(target.call.query());
				PackedCostSession producerSession = producer.model.openSession(producer.call.query())) {
			Fixture sourceFixture = foreignOutput ? producer : target;
			PackedCostSession sourceSession = foreignOutput ? producerSession : targetSession;
			int actualLeft = sourceFixture.priceFilteredPrefix(sourceSession);
			PackedCostEstimate output = sourceFixture.pricePath(sourceSession);
			declare(sourceFixture, RowScope.FOR_CONTEXT, CostScope.TOTAL_FOR_CONTEXT, 7.0d, 37.0d, false);
			sourceSession.appendFactor(sourceFixture.call.rightRelationId(),
					sourceFixture.restrictedContext(actualLeft), output);
			LmdbQualifiedRowFallbackNativeSessionTest.assertBindingOnly(output);
			assertTrue(output.evidenceStateId() > 0, "the opaque output was produced by actual public callbacks");
			LmdbOperatorFeedbackStats feedback = trainedJoinFeedback(target, directory);
			AtomicInteger calls = new AtomicInteger();
			when(target.runtime.operatorFeedback(any(), anyDouble(), anyDouble(), anyDouble(), anyDouble(), any()))
					.thenAnswer(invocation -> {
						calls.incrementAndGet();
						return feedback.estimate(invocation.getArgument(0), invocation.getArgument(1),
								invocation.getArgument(2), invocation.getArgument(3), invocation.getArgument(4),
								invocation.getArgument(5));
					});
			output.setEstimateProvenance("supplemental-join", "actual-opaque-output");
			targetSession.refineOperator(target.call.operatorRelationId(),
					target.call.operatorContext(2.0d, 101.0d, 0, 0), output);
			assertEquals(0, calls.get(), "zero context IDs do not erase the supplied opaque output's origin");
			assertEquals(7.0d, output.outputRows());
			assertTrue(output.hasContextualOutputRows());
			assertEquals(33.0d, output.workRows());
			assertEquals(3.0d, output.sequentialRows());
			assertEquals(9.0d, output.pathExpansions());
			assertEquals(7.0d, output.resultRows());
			assertEquals(0, targetSession.detachEvidence(new int[] { output.evidenceStateId() })
					.requestedStateOrdinal(0), "no actual input was supplied to authenticate a population");
			assertEquals(0, targetSession.exactContinuationIdentity(output));
		}
	}

